const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 1_000_000;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const JOB_PATH_RE = /^\/api\/jobs\/([^/]+)$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalidRequest(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  res.setHeader('Allow', allowed.join(', '));
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allowed.join(' or ')}.`);
}

/** Reads the whole body as UTF-8. Resolves null when it exceeds the size cap. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      if (tooLarge) return;
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Reads an integer field with a default; records a field error when the value is present but invalid. */
function intField(obj: Record<string, unknown>, name: string, def: number, min: number, max: number, fields: FieldError[]): number {
  if (!Object.hasOwn(obj, name)) return def;
  const v = obj[name];
  if (typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max) return v;
  fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
  return def;
}

function selectJobById(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

function selectJobByKey(key: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
}

function isUniqueViolation(e: unknown): boolean {
  return e instanceof Error && /UNIQUE constraint failed/.test(e.message);
}

type CreateOutcome = { kind: 'created'; row: JobRow } | { kind: 'replay'; row: JobRow } | { kind: 'conflict' };

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const fields: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return invalidRequest(res, fields);
  }
  if (body === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
    return invalidRequest(res, fields);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch {
    fields.push({ field: 'body', message: 'body is not valid JSON' });
    return invalidRequest(res, fields);
  }
  if (!isPlainObject(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return invalidRequest(res, fields);
  }

  for (const name of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'unknown field' });
  }

  let input = '';
  if (typeof parsed.input === 'string' && parsed.input.length >= 1 && parsed.input.length <= 1000 && parsed.input.trim() !== '') {
    input = parsed.input;
  } else {
    fields.push({ field: 'input', message: 'must be a string of 1 to 1000 characters that is not only whitespace' });
  }
  const steps = intField(parsed, 'steps', 5, 1, 20, fields);
  const failAttempts = intField(parsed, 'failAttempts', 0, 0, 5, fields);

  if (fields.length > 0) return invalidRequest(res, fields);

  // Canonical payload in fixed key order, with defaults applied, for idempotency comparison.
  const payload = JSON.stringify({ input, steps, failAttempts });
  const idempotencyKey = key;

  const outcome = tx(db, (): CreateOutcome => {
    if (idempotencyKey !== undefined) {
      const existing = selectJobByKey(idempotencyKey);
      if (existing) return existing.payload === payload ? { kind: 'replay', row: existing } : { kind: 'conflict' };
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    try {
      db.prepare(
        `INSERT INTO jobs(id, status, input, steps, fail_attempts, attempts, progress_completed,
                          result_output, error, created_at, updated_at, run_after, idempotency_key, payload)
         VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0, ?, ?)`,
      ).run(id, input, steps, failAttempts, now, now, idempotencyKey ?? null, payload);
    } catch (e) {
      // Backstop for the UNIQUE index: if another writer won the race, treat it as a replay.
      if (idempotencyKey !== undefined && isUniqueViolation(e)) {
        const existing = selectJobByKey(idempotencyKey);
        if (existing) return existing.payload === payload ? { kind: 'replay', row: existing } : { kind: 'conflict' };
      }
      throw e;
    }
    return { kind: 'created', row: selectJobById(id)! };
  });

  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, rowToJob(outcome.row));
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT last_seen FROM heartbeat WHERE id = 1').get() as { last_seen: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.last_seen < 3000;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function handleRequest(req: IncomingMessage, res: ServerResponse): Promise<void> | void {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, ['GET']);
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(rowToJob) });
    }
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = JOB_PATH_RE.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No job with that id.');
    }
    const row = selectJobById(id);
    if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
    return send(res, 200, rowToJob(row));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => handleRequest(req, res))
    .catch((e: unknown) => {
      console.error('request failed:', e);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
      else res.end();
    });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  const closeDb = (database: DatabaseSync): void => {
    try {
      database.close();
    } catch {
      // Already closed or unusable; exiting anyway.
    }
  };
  setTimeout(() => {
    closeDb(db);
    process.exit(0);
  }, 2000).unref();
  server.close(() => {
    closeDb(db);
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

