import { openDatabase, tx, type JobRow } from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const IDLE_MS = 200;
const HEARTBEAT_MS = 500;

const db = openDatabase();
let stopping = false;
/** Pending sleeps, so a shutdown signal can wake them immediately. */
const wakers = new Set<() => void>();

/** Sleeps for `ms`, or until shutdown is requested, whichever comes first. */
function pause(ms: number): Promise<void> {
  return new Promise((resolve) => {
    const done = (): void => {
      clearTimeout(timer);
      wakers.delete(done);
      resolve();
    };
    const timer = setTimeout(done, ms);
    wakers.add(done);
  });
}

function requestStop(): void {
  if (stopping) return;
  stopping = true;
  for (const wake of [...wakers]) wake();
}
process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

function beat(): void {
  db.prepare(
    'INSERT INTO heartbeat(id, last_seen) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET last_seen = excluded.last_seen',
  ).run(Date.now());
}

/** Any row still `running` belongs to a worker that died, because only one worker runs at a time. */
function recoverOrphans(): void {
  tx(db, () => {
    db.prepare(
      "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
    ).run(new Date().toISOString());
  });
}

interface Claimed {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempt: number;
}

/** Atomically takes the oldest runnable queued job and marks it running for its next attempt. */
function claim(): Claimed | undefined {
  return tx(db, (): Claimed | undefined => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    // Capped at MAX_ATTEMPTS so a crash-recovered job never runs past its attempt budget.
    const attempt = Math.min(row.attempts + 1, MAX_ATTEMPTS);
    const updated = db
      .prepare("UPDATE jobs SET status = 'running', attempts = ?, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'")
      .run(attempt, new Date().toISOString(), row.id);
    if (updated.changes !== 1) return undefined;
    return { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempt };
  });
}

/** Puts a running job back in the queue because the worker is stopping before it finished. */
function requeue(id: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(new Date().toISOString(), id);
}

async function runAttempt(job: Claimed): Promise<void> {
  // The first step's time elapses before anything is recorded, so a failing attempt fails at its first step.
  await pause(STEP_MS);
  if (stopping) return requeue(job.id);

  if (job.attempt <= job.failAttempts) {
    const now = new Date().toISOString();
    if (job.attempt < MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(Date.now() + RETRY_DELAY_MS, now, job.id);
    } else {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(now, job.id);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    if (step > 1) {
      await pause(STEP_MS);
      if (stopping) return requeue(job.id);
    }
    db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
      step,
      new Date().toISOString(),
      job.id,
    );
  }

  db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.input.toUpperCase(), job.steps, new Date().toISOString(), job.id);
}

const heartbeatTimer = setInterval(() => {
  try {
    beat();
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

beat();
recoverOrphans();
console.log('worker started');

while (!stopping) {
  let job: Claimed | undefined;
  try {
    job = claim();
  } catch (e) {
    console.error('claim failed:', e);
    await pause(RETRY_DELAY_MS);
    continue;
  }
  if (!job) {
    await pause(IDLE_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed:`, e);
    try {
      requeue(job.id);
    } catch {
      // The job stays running and is recovered on the next start.
    }
  }
}

clearInterval(heartbeatTimer);
setTimeout(() => process.exit(0), 3000).unref();
try {
  // Zero marks the worker down immediately, rather than after the 3 s staleness window.
  db.prepare('UPDATE heartbeat SET last_seen = 0 WHERE id = 1').run();
  db.close();
} catch (e) {
  console.error('shutdown error:', e);
}
console.log('worker stopped');
process.exit(0);

